т</label><select id="itemPriority" class="form-select"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100" onclick="addProtocolItem()">Создать</button></div></div></div></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>№</th><th>Поручение</th><th>Исполнитель</th><th>Срок</th><th>Статус</th><th style="width:130px">Прогресс</th><th style="width:190px"></th></tr></thead><tbody id="protocolRows"></tbody></table></div></div><div class="modal-footer"><button id="btnCloseMeeting" class="btn btn-outline-danger me-auto" onclick="closeMeeting()"><i class="bi bi-lock me-1"></i>Закрыть протокол</button><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Закрыть окно</button></div></div></div></div>
