@push('scripts')
<script>
let currentMeeting=null;function escM(v){return $('<div>').text(v??'').html()}function ms(s){return {draft:'Черновик',active:'В работе',closed:'Закрыт'}[s]||s}function ts(s){return {new:'Новая',in_progress:'В работе',review:'На проверке',completed:'Выполнено',cancelled:'Отменено'}[s]||s}function localM(v){if(!v)return'';const d=new Date(v),z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}
function loadMeetings(){$.get('{{ route('meetings.index') }}',{q:$('#meetingQ').val(),status:$('#meetingStatus').val()},r=>{let h='';r.data.forEach(m=>{const items=m.items||[],done=items.filter(x=>x.task?.status==='completed').length,over=items.filter(x=>x.task?.is_overdue).length,review=items.filter(x=>x.task?.status==='review').length,p=items.length?Math.round(done/items.length*100):0;h+=`<div class="col-12"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex gap-3 flex-wrap"><div class="flex-grow-1"><h5 class="mb-1">${escM(m.title)}</h5><div class="text-muted small">${new Date(m.held_at).toLocaleString('ru-RU')}${m.location?' · '+escM(m.location):''}</div></div><span class="badge text-bg-${m.status==='closed'?'secondary':m.status==='active'?'primary':'light'} border">${ms(m.status)}</span></div><div class="d-flex gap-3 flex-wrap mt-3 small"><span>Поручений: <b>${items.length}</b></span><span class="text-success">Выполнено: <b>${done}</b></span><span class="text-warning">На проверке: <b>${review}</b></span><span class="text-danger">Просрочено: <b>${over}</b></span></div><div class="d-flex align-items-center gap-2 mt-3"><div class="progress flex-grow-1" style="height:8px"><div class="progress-bar" style="width:${p}%"></div></div><span class="small">${p}%</span><button class="btn btn-sm btn-outline-primary ms-2" onclick="openMeeting(${m.id})">Открыть протокол</button></div></div></div></div>`});$('#meetingList').html(h||'<div class="col-12"><div class="alert alert-light border text-center">Совещаний пока нет</div></div>')})}
function newMeeting(){$('#meetingForm')[0].reset();$('#meetingId').val('');$('#meetingFormTitle').text('Новое совещание');$('#meetingForm [name=status]').val('active');$('#meetingError').addClass('d-none')}
function fillMeetingForm(m){newMeeting();$('#meetingId').val(m.id);$('#meetingFormTitle').text('Редактировать совещание');$('#meetingForm [name=title]').val(m.title);$('#meetingForm [name=held_at]').val(localM(m.held_at));$('#meetingForm [name=location]').val(m.location||'');$('#meetingForm [name=chairman_id]').val(m.chairman_id||'');$('#meetingForm [name=secretary_id]').val(m.secretary_id||'');$('#meetingForm [name=notes]').val(m.notes||'');$('#meetingForm [name=status]').val(m.status);$('#meetingForm [name="participants[]"]').val((m.participants||[]).map(x=>String(x.id)))}
$('#meetingForm').on('submit',function(e){e.preventDefault();const fd=new FormData(this),d={participants:[]};for(const [k,v] of fd.entries()){if(k==='participants[]')d.participants.push(v);else d[k]=v}const id=$('#meetingId').val();$.ajax({url:id?`{{ url('/ajax/meetings') }}/${id}`:'{{ route('meetings.store') }}',method:id?'PATCH':'POST',data:d}).done(()=>{bootstrap.Modal.getInstance(document.getElementById('meetingModal')).hide();loadMeetings();if(id)openMeeting(id)}).fail(x=>$('#meetingError').removeClass('d-none').text(x.responseJSON?.message||'Ошибка сохранения'))});
function openMeeting(id){$.get(`{{ url('/ajax/meetings') }}/${id}`,m=>{currentMeeting=m;$('#protocolTitle').text(m.title);$('#protocolMeta').text(`${new Date(m.held_at).toLocaleString('ru-RU')}${m.location?' · '+m.location:''}${m.chairman?' · председатель '+m.chairman.last_name+' '+m.chairman.first_name:''}`);$('#protocolNotes').html(m.notes?`<div class="alert alert-light border"><b>Повестка / заметки:</b><div class="mt-1">${escM(m.notes)}</div></div>`:'');$('#meetingPrintLink').attr('href',`{{ url('/meetings') }}/${m.id}/print`);$('#archiveMeetingBtn').toggleClass('d-none',m.status!=='closed');renderProtocol(m);$('#btnAddItem').toggle(m.status!=='closed');$('#btnCloseMeeting').toggle(m.status!=='closed');bootstrap.Modal.getOrCreateInstance(document.getElementById('protocolModal')).show()})}
function renderProtocol(m){const items=m.items||[],done=items.filter(x=>x.task?.status==='completed').length,over=items.filter(x=>x.task?.is_overdue).length,review=items.filter(x=>x.task?.status==='review').length;$('#protocolStats').html(`<div class="col-6 col-md-3"><div class="border rounded p-3"><div class="text-muted small">Поручений</div><div class="fs-4 fw-bold">${items.length}</div></div></div><div class="col-6 col-md-3"><div class="border rounded p-3"><div class="text-muted small">Выполнено</div><div class="fs-4 fw-bold text-success">${done}</div></div></div><div class="col-6 col-md-3"><div class="border rounded p-3"><div class="text-muted small">На проверке</div><div class="fs-4 fw-bold text-warning">${review}</div></div></div><div class="col-6 col-md-3"><div class="border rounded p-3"><div class="text-muted small">Просрочено</div><div class="fs-4 fw-bold text-danger">${over}</div></div></div>`);let h='';items.forEach((i,idx)=>{const t=i.task||{},overdue=t.is_overdue,progress=t.progress||0,assignee=t.assignee||i.assignee,due=t.due_at||i.due_at,canEdit=m.status!=='closed';h+=`<tr class="${overdue?'table-danger':''}"><td>${i.number}</td><td>${escM(i.instruction)}</td><td><b>${escM((assignee?.last_name||'')+' '+(assignee?.first_name||''))}</b><div class="small text-muted">${escM(assignee?.department?.name||'')}</div>${t.assigned_to&&t.assigned_to!==i.assigned_to?'<div class="small text-primary">исполнитель изменён после протокола</div>':''}</td><td class="text-nowrap">${due?new Date(due).toLocaleString('ru-RU'):'—'}${t.due_at&&i.due_at&&new Date(t.due_at).getTime()!==new Date(i.due_at).getTime()?'<div class="small text-primary">срок перенесён</div>':''}</td><td>${overdue?'<span class="badge text-bg-danger">Просрочено</span>':`<span class="badge text-bg-light border">${ts(t.status||'new')}</span>`}</td><td><div class="progress" style="height:18px"><div class="progress-bar" style="width:${progress}%">${progress}%</div></div></td><td class="text-end"><div class="btn-group btn-group-sm">${t.id?`<a class="btn btn-outline-primary" href="{{ url('/tasks') }}?task=${t.id}" title="Задача"><i class="bi bi-check2-square"></i></a>`:''}${canEdit?`<button class="btn btn-outline-secondary" onclick="editProtocolItem(${i.id})" title="Изменить"><i class="bi bi-pencil"></i></button><button class="btn btn-outline-secondary" onclick="moveProtocolItem(${i.id},-1)" ${idx===0?'disabled':''} title="Выше"><i class="bi bi-arrow-up"></i></button><button class="btn btn-outline-secondary" onclick="moveProtocolItem(${i.id},1)" ${idx===items.length-1?'disabled':''} title="Ниже"><i class="bi bi-arrow-down"></i></button><button class="btn btn-outline-danger" onclick="deleteProtocolItem(${i.id})" title="Удалить"><i class="bi bi-trash"></i></button>`:''}</div></td></tr>`});$('#protocolRows').html(h||'<tr><td colspan="7" class="text-center text-muted py-4">Поручений ещё нет</td></tr>')}
function editCurrentMeeting(){if(!currentMeeting)return;fillMeetingForm(currentMeeting);bootstrap.Modal.getOrCreateInstance(document.getElementById('meetingModal')).show()}
function meetingMaterials(){if(currentMeeting)openEntityCollab('meeting',currentMeeting.id,'Материалы: '+currentMeeting.title)}
function archiveCurrentMeeting(){if(currentMeeting)archiveEntity('meeting',currentMeeting.id)}
function addProtocolItem(){if(!currentMeeting)return;const instruction=$('#itemInstruction').val().trim();if(!instruction){alert('Введите поручение');return}$.post(`{{ url('/ajax/meetings') }}/${currentMeeting.id}/items`,{instruction,assigned_to:$('#itemAssignee').val(),due_at:$('#itemDueAt').val(),priority:$('#itemPriority').val()}).done(()=>{$('#itemInstruction').val('');$('#itemDueAt').val('');openMeeting(currentMeeting.id);loadMeetings()}).fail(x=>alert(x.responseJSON?.message||'Ошибка создания поручения'))}
function editProtocolItem(id){const i=(currentMeeting.items||[]).find(x=>x.id===id);if(!i)return;$('#editItemId').val(i.id);$('#editItemInstruction').val(i.instruction);$('#editItemAssignee').val(i.task?.assigned_to||i.assigned_to);$('#editItemDueAt').val(localM(i.task?.due_at||i.due_at));$('#editItemPriority').val(i.task?.priority||i.priority);bootstrap.Modal.getOrCreateInstance(document.getElementById('itemEditModal')).show()}
$('#itemEditForm').on('submit',function(e){e.preventDefault();if(!currentMeeting)return;const id=$('#editItemId').val();$.ajax({url:`{{ url('/ajax/meetings') }}/${currentMeeting.id}/items/${id}`,method:'PATCH',data:{instruction:$('#editItemInstruction').val(),assigned_to:$('#editItemAssignee').val(),due_at:$('#editItemDueAt').val(),priority:$('#editItemPriority').val()}}).done(()=>{bootstrap.Modal.getInstance(document.getElementById('itemEditModal')).hide();openMeeting(currentMeeting.id);loadMeetings()}).fail(x=>alert(x.responseJSON?.message||'Ошибка изменения поручения'))})
function deleteProtocolItem(id){if(!currentMeeting||!confirm('Удалить пункт протокола? Связанная незавершённая задача будет отменена, но история сохранится.'))return;$.ajax({url:`{{ url('/ajax/meetings') }}/${currentMeeting.id}/items/${id}`,method:'DELETE'}).done(()=>{openMeeting(currentMeeting.id);loadMeetings()}).fail(x=>alert(x.responseJSON?.message||'Ошибка удаления'))}
function moveProtocolItem(id,dir){if(!currentMeeting)return;let ids=(currentMeeting.items||[]).map(x=>x.id),idx=ids.indexOf(id),to=idx+dir;if(idx<0||to<0||to>=ids.length)return;[ids[idx],ids[to]]=[ids[to],ids[idx]];$.post(`{{ url('/ajax/meetings') }}/${currentMeeting.id}/items/reorder`,{item_ids:ids}).done(()=>openMeeting(currentMeeting.id)).fail(x=>alert(x.responseJSON?.message||'Ошибка перенумерации'))}
function closeMeeting(){if(!currentMeeting||!confirm('Закрыть протокол? Поручения продолжат выполняться, но структура протокола будет зафиксирована.'))return;$.post(`{{ url('/ajax/meetings') }}/${currentMeeting.id}/close`).done(()=>{openMeeting(currentMeeting.id);loadMeetings()}).fail(x=>alert(x.responseJSON?.message||'Ошибка'))}
$('#meetingQ').on('input',()=>{clearTimeout(window.meetT);window.meetT=setTimeout(loadMeetings,300)});$('#meetingStatus').on('change',loadMeetings);loadMeetings();
</script>
